import math


def _parse_int(s: str) -> int:
    if len(s) <= 4000:
        return int(s)
    res = 0
    for i in range(0, len(s), 1000):
        chunk = s[i : i + 1000]
        res = res * (10 ** len(chunk)) + int(chunk)
    return res


def _trunc_div_mod(a: int, b: int) -> tuple[int, int]:
    if b == 0:
        raise ValueError("Division or remainder by zero")
    q = abs(a) // abs(b)
    if (a < 0) ^ (b < 0):
        q = -q
    r = a - q * b
    return q, r


def _tokenize(expr: str) -> list[tuple[str, object]]:
    tokens: list[tuple[str, object]] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            tokens.append(("NUM", _parse_int(expr[start:i])))
        elif ch in "+-*/%^!()":
            tokens.append(("OP", ch))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {ch!r}")
    tokens.append(("EOF", None))
    return tokens


def evaluate(expr: str) -> int:
    tokens = _tokenize(expr)
    if tokens[0][0] == "EOF":
        raise ValueError("Empty expression")
    pos = 0

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while True:
            tok_type, tok_val = tokens[pos]
            if tok_type == "OP" and tok_val in ("+", "-"):
                pos += 1
                rhs = parse_mul()
                if tok_val == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            tok_type, tok_val = tokens[pos]
            if tok_type == "OP" and tok_val in ("*", "/", "%", "("):
                if tok_val == "(":
                    rhs = parse_unary()
                    val *= rhs
                else:
                    pos += 1
                    rhs = parse_unary()
                    if tok_val == "*":
                        val *= rhs
                    elif tok_val == "/":
                        val, _ = _trunc_div_mod(val, rhs)
                    else:
                        _, val = _trunc_div_mod(val, rhs)
            else:
                break
        return val

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while tokens[pos] == ("OP", "-"):
            pos += 1
            neg = not neg
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        nonlocal pos
        base = parse_postfix()
        if tokens[pos] == ("OP", "^"):
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent")
            return pow(base, exp)
        return base

    def parse_postfix() -> int:
        nonlocal pos
        val = parse_primary()
        while tokens[pos] == ("OP", "!"):
            pos += 1
            if val < 0:
                raise ValueError("Factorial of negative number")
            val = math.factorial(val)
        return val

    def parse_primary() -> int:
        nonlocal pos
        tok_type, tok_val = tokens[pos]
        if tok_type == "NUM":
            pos += 1
            return tok_val  # type: ignore[return-value]
        if tok_type == "OP" and tok_val == "(":
            pos += 1
            val = parse_add()
            if tokens[pos] != ("OP", ")"):
                raise ValueError("Expected ')'")
            pos += 1
            return val
        raise ValueError(f"Unexpected token: {tokens[pos]!r}")

    result = parse_add()
    if tokens[pos][0] != "EOF":
        raise ValueError(f"Unexpected trailing token: {tokens[pos]!r}")
    return result
